-- ------------------------------------------------------------------------
-- 0008_rbac_enforcement.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- RBAC — server-side enforcement.
--
-- Until now the role → action matrix (app_roles, edited in Admin → Roles &
-- Permissions) was only honoured by the browser: can(action) hid buttons and
-- blocked routes, but Postgres itself let any authenticated user write any
-- row it could reach. Anyone with the anon key and a login could bypass the UI.
--
-- This migration moves the same matrix into the database:
--   * has_perm('<action>') resolves the signed-in user's role against
--     app_roles.permissions — the very rows the admin UI edits.
--   * app_roles is seeded with the app's DEFAULT_PERMS (src/lib/rbac.ts) so
--     the matrix is never empty (an empty matrix would lock everyone out).
--   * every RLS policy that previously said "authenticated" or "is_admin()"
--     now names the action it needs.
--   * spare_requests approval columns are guarded per stage by a trigger,
--     since RLS cannot express "may change these columns only".
--
-- Keep this file in sync with src/lib/rbac.ts when actions/roles change.
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- Super admins — the dev/support logins that always hold every right (mirrors
-- SUPER_ADMINS in src/lib/auth.tsx). A table, so it can be edited in SQL
-- without a code deploy.
-- ---------------------------------------------------------------------------
create table if not exists public.app_super_admins (
  email      text primary key,
  created_at timestamptz not null default now()
);
insert into public.app_super_admins (email) values
  ('service.almsind@gmail.com'),
  ('devika.m@airliquide.com'),
  ('devikamunusamy@gmail.com'),
  ('mmdev74@gmail.com')
on conflict (email) do nothing;

alter table public.app_super_admins enable row level security;
drop policy if exists asa_read on public.app_super_admins;
create policy asa_read on public.app_super_admins for select using (public.is_admin());
-- No write policy: the list is maintained in SQL only (service role / SQL editor).

create or replace function public.is_super_admin()
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.app_super_admins s where lower(s.email) = lower(coalesce(auth.email(), ''))
  );
$$;

-- Admin = profiles.role 'admin', or a super admin login.
create or replace function public.is_admin()
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin'
  ) or public.is_super_admin();
$$;

-- The signed-in user's RBAC role key (profiles.role), defaulting to engineer.
create or replace function public.my_role()
returns text language sql stable security definer set search_path = public as $$
  select coalesce(nullif(lower(trim(p.role)), ''), 'engineer')
    from public.profiles p where p.id = auth.uid();
$$;

-- The extra actions granted to this user directly, on top of their role
-- (profiles.extra_permissions — see 0007_user_access.sql).
create or replace function public.my_extra_perms()
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce(p.extra_permissions, '[]'::jsonb) from public.profiles p where p.id = auth.uid();
$$;

-- Does the signed-in user hold `action`? Admins and super admins hold every
-- action. Otherwise the action must appear in app_roles.permissions for their
-- role, or in their own extra_permissions; a role with no row (or an empty
-- array) falls back to 'engineer' so a half-configured matrix degrades to
-- least privilege rather than lock-out.
create or replace function public.has_perm(action text)
returns boolean language sql stable security definer set search_path = public as $$
  with role_row as (
    select r.permissions from public.app_roles r
     where r.role = public.my_role() and jsonb_array_length(coalesce(r.permissions, '[]'::jsonb)) > 0
  ),
  fallback as (
    select r.permissions from public.app_roles r where r.role = 'engineer'
  ),
  perms as (
    select permissions from role_row
    union all
    select permissions from fallback where not exists (select 1 from role_row)
  )
  select public.is_admin()
      or exists (select 1 from perms p where p.permissions ? action)
      or public.my_extra_perms() ? action;
$$;

grant execute on function public.is_super_admin()  to authenticated;
grant execute on function public.my_role()         to authenticated;
grant execute on function public.my_extra_perms()  to authenticated;
grant execute on function public.has_perm(text)    to authenticated;

-- ---------------------------------------------------------------------------
-- Seed app_roles with the app's starting matrix (src/lib/rbac.ts DEFAULT_PERMS)
-- so enforcement has something to enforce. Roles that already carry a
-- non-empty permission list are left untouched — admin edits win.
-- ---------------------------------------------------------------------------
do $$
declare
  admin_mods text[] := array['mod:/users','mod:/roles','mod:/admin-config'];
  open_mods  text[] := array[
    'mod:/','mod:/daily-review','mod:/parties','mod:/product-master','mod:/user-master',
    'mod:/parts','mod:/warranties','mod:/contracts','mod:/request-registration',
    'mod:/pending-registrations','mod:/field-calls','mod:/installations','mod:/pm-calls',
    'mod:/reports','mod:/spare-requests','mod:/spare-consumption','mod:/feedback',
    'mod:/failure-report','mod:/kpi','mod:/settings','mod:/version-history'];
  all_actions text[] := array[
    'calls.view','calls.create','calls.edit','calls.report','request.create','pending.register',
    'spare.request','spare.approve_rm','spare.approve_commercial','spare.approve_nsm','spare.dispatch',
    'consumption.view','masters.view','masters.edit','reports.view','dashboard.view','feedback.view',
    'users.manage','config.manage','rbac.manage'];
  defs jsonb := jsonb_build_object(
    'admin',             to_jsonb(all_actions || open_mods || admin_mods),
    'nsm',               to_jsonb(array['calls.view','masters.view','consumption.view','reports.view','dashboard.view','feedback.view','spare.approve_nsm'] || open_mods),
    'rgm',               to_jsonb(array['calls.view','calls.create','calls.edit','calls.report','request.create','spare.request','spare.approve_rm','consumption.view','masters.view','reports.view','dashboard.view','feedback.view'] || open_mods),
    'rm',                to_jsonb(array['calls.view','calls.create','calls.edit','calls.report','request.create','spare.request','spare.approve_rm','consumption.view','masters.view','reports.view','dashboard.view','feedback.view'] || open_mods),
    'engineer',          to_jsonb(array['calls.view','calls.report','request.create','spare.request','consumption.view','reports.view','dashboard.view'] || open_mods),
    'hotline',           to_jsonb(array['calls.view','calls.create','request.create','pending.register','spare.approve_rm','masters.view','dashboard.view'] || open_mods),
    'spare_coordinator', to_jsonb(array['calls.view','spare.request','spare.approve_rm','spare.dispatch','consumption.view','reports.view','dashboard.view'] || open_mods),
    'stores_incharge',   to_jsonb(array['calls.view','spare.dispatch','consumption.view','reports.view','dashboard.view'] || open_mods),
    'tally_coordinator', to_jsonb(array['calls.view','consumption.view','reports.view','feedback.view','dashboard.view'] || open_mods),
    'commercial',        to_jsonb(array['calls.view','consumption.view','reports.view','feedback.view','dashboard.view','masters.view','spare.approve_commercial'] || open_mods)
  );
  labels jsonb := jsonb_build_object(
    'admin','Admin / Super Admin', 'nsm','NSM (National Service Manager)', 'rgm','Regional Manager',
    'rm','Reporting Manager', 'engineer','Engineer', 'hotline','Hotline Engineer',
    'spare_coordinator','Spare Coordinator', 'stores_incharge','Stores Incharge',
    'tally_coordinator','Tally Coordinator', 'commercial','Commercial');
  k text;
begin
  for k in select jsonb_object_keys(defs) loop
    insert into public.app_roles (role, label, permissions)
    values (k, labels ->> k, defs -> k)
    on conflict (role) do update
      set label       = coalesce(nullif(public.app_roles.label, ''), excluded.label),
          permissions = case
                          when jsonb_array_length(coalesce(public.app_roles.permissions, '[]'::jsonb)) = 0
                          then excluded.permissions
                          else public.app_roles.permissions
                        end,
          updated_at  = now();
  end loop;
end $$;

-- ===========================================================================
-- Policies — each one now names the action it requires.
-- ===========================================================================

-- profiles: own row always readable; managing users needs users.manage.
drop policy if exists profiles_self_read on public.profiles;
create policy profiles_self_read on public.profiles for select
  using (id = auth.uid() or public.is_admin() or public.has_perm('users.manage'));
drop policy if exists profiles_admin_write on public.profiles;
create policy profiles_admin_write on public.profiles for all
  using (public.has_perm('users.manage')) with check (public.has_perm('users.manage'));

-- Masters & catalog: reference data every signed-in user needs to fill a call
-- in (parties, products, parts, value lists), so reads stay open to any
-- authenticated user; changing a master needs masters.edit.
do $$
declare t text;
begin
  foreach t in array array['parties','products','parts','masters'] loop
    execute format('drop policy if exists %1$s_read on public.%1$s;', t);
    execute format('create policy %1$s_read on public.%1$s for select using (auth.role() = ''authenticated'');', t);
    execute format('drop policy if exists %1$s_admin_write on public.%1$s;', t);
    execute format('drop policy if exists %1$s_write on public.%1$s;', t);
    execute format('create policy %1$s_write on public.%1$s for all using (public.has_perm(''masters.edit'')) with check (public.has_perm(''masters.edit''));', t);
  end loop;
end $$;

-- user_directory: readable by anyone who may see calls (it drives the
-- reporting tree); maintained by user managers.
drop policy if exists ud_read on public.user_directory;
create policy ud_read on public.user_directory for select using (auth.role() = 'authenticated');
drop policy if exists ud_admin_write on public.user_directory;
drop policy if exists ud_write on public.user_directory;
create policy ud_write on public.user_directory for all
  using (public.has_perm('users.manage')) with check (public.has_perm('users.manage'));

-- app_roles: everyone reads the matrix (the client needs it to gate the UI);
-- only rbac.manage may change it.
drop policy if exists ar_read on public.app_roles;
create policy ar_read on public.app_roles for select using (auth.role() = 'authenticated');
drop policy if exists ar_admin_write on public.app_roles;
drop policy if exists ar_write on public.app_roles;
create policy ar_write on public.app_roles for all
  using (public.has_perm('rbac.manage')) with check (public.has_perm('rbac.manage'));

-- calls: the reporting-tree scope still applies, on top of the action.
do $calls_guard$ begin
-- 0040_call_tables_split.sql replaces public.calls with a VIEW over the three
-- typed call tables. What follows is table-only work, so on a project that has
-- already been split it has to be SKIPPED, not attempted — otherwise replaying
-- this file (which re-running any bundle does) dies with
--   ERROR 42809: cannot create index on relation "calls"
-- or "calls is not a table". On an unsplit project it runs exactly as before.
if (select c.relkind from pg_class c join pg_namespace n on n.oid = c.relnamespace
     where n.nspname = 'public' and c.relname = 'calls') = 'r' then
execute $calls_sql$
drop policy if exists calls_scoped_read on public.calls;
create policy calls_scoped_read on public.calls for select
  using (public.has_perm('calls.view') and public.can_see_call(allocated_to));
drop policy if exists calls_insert on public.calls;
create policy calls_insert on public.calls for insert
  with check (public.has_perm('calls.create'));
drop policy if exists calls_update on public.calls;
create policy calls_update on public.calls for update
  using ((public.has_perm('calls.edit') or public.has_perm('calls.report')) and public.can_see_call(allocated_to))
  with check ((public.has_perm('calls.edit') or public.has_perm('calls.report')) and public.can_see_call(allocated_to));
$calls_sql$;
end if;
end $calls_guard$;

-- pending registrations: Hotline registers them; scope still applies to reads.
drop policy if exists pend_read on public.pending_registrations;
create policy pend_read on public.pending_registrations for select
  using (public.is_admin() or created_by = auth.uid()
    or (public.has_perm('calls.view')
        and lower(trim(engineer)) in (select lower(trim(n)) from public.visible_engineer_names() as v(n))));
drop policy if exists pend_insert on public.pending_registrations;
create policy pend_insert on public.pending_registrations for insert
  with check (public.has_perm('pending.register') or public.has_perm('request.create'));
drop policy if exists pend_update on public.pending_registrations;
create policy pend_update on public.pending_registrations for update
  using (public.has_perm('pending.register') or public.has_perm('calls.create'))
  with check (public.has_perm('pending.register') or public.has_perm('calls.create'));

-- call requests: raising one needs request.create; acting on one needs
-- calls.create (the Hotline/admin who turns it into a call).
drop policy if exists cr_insert on public.call_requests;
create policy cr_insert on public.call_requests for insert
  with check (public.has_perm('request.create'));
drop policy if exists cr_update on public.call_requests;
create policy cr_update on public.call_requests for update
  using (public.has_perm('calls.create') or public.has_perm('pending.register') or created_by = auth.uid())
  with check (public.has_perm('calls.create') or public.has_perm('pending.register') or created_by = auth.uid());

-- reports: visible with the parent call; writing one is calls.report.
drop policy if exists reports_read on public.reports;
create policy reports_read on public.reports for select
  using (public.is_admin() or (public.has_perm('calls.view') and exists (
    select 1 from public.calls c where c.ucn = reports.ucn and public.can_see_call(c.allocated_to))));
drop policy if exists reports_write on public.reports;
create policy reports_write on public.reports for all
  using (public.has_perm('calls.report')) with check (public.has_perm('calls.report'));

-- consumption / feedback.
drop policy if exists cons_read on public.spare_consumption;
create policy cons_read on public.spare_consumption for select using (public.has_perm('consumption.view'));
drop policy if exists cons_write on public.spare_consumption;
create policy cons_write on public.spare_consumption for insert
  with check (public.has_perm('calls.report') or public.has_perm('spare.dispatch'));

drop policy if exists fb_read on public.feedback;
create policy fb_read on public.feedback for select
  using (public.has_perm('feedback.view') or public.has_perm('calls.report'));
drop policy if exists fb_write on public.feedback;
create policy fb_write on public.feedback for insert
  with check (public.has_perm('calls.report') or public.has_perm('feedback.view'));

-- spare requests: raising needs spare.request; reading follows the reporting
-- tree, plus anyone in the approval chain (they must see what they approve).
create or replace function public.can_approve_spares()
returns boolean language sql stable security definer set search_path = public as $$
  select public.has_perm('spare.approve_rm')
      or public.has_perm('spare.approve_commercial')
      or public.has_perm('spare.approve_nsm')
      or public.has_perm('spare.dispatch');
$$;
grant execute on function public.can_approve_spares() to authenticated;

drop policy if exists sr_read on public.spare_requests;
create policy sr_read on public.spare_requests for select
  using (public.is_admin() or created_by = auth.uid() or lower(engineer_email) = lower(auth.email())
    or public.can_approve_spares()
    or lower(trim(engineer)) in (select lower(trim(n)) from public.visible_engineer_names() as v(n)));
drop policy if exists sr_insert on public.spare_requests;
create policy sr_insert on public.spare_requests for insert
  with check (public.has_perm('spare.request'));
drop policy if exists sr_update on public.spare_requests;
create policy sr_update on public.spare_requests for update
  using (public.can_approve_spares() or created_by = auth.uid())
  with check (public.can_approve_spares() or created_by = auth.uid());

-- Request lines: readable with their request; the requester writes their own
-- lines (the app inserts them right after the request), approvers may update.
drop policy if exists srl_read on public.spare_request_lines;
create policy srl_read on public.spare_request_lines for select
  using (exists (select 1 from public.spare_requests r where r.uid = spare_request_lines.request_uid));
drop policy if exists srl_write on public.spare_request_lines;
drop policy if exists srl_insert on public.spare_request_lines;
create policy srl_insert on public.spare_request_lines for insert
  with check (public.has_perm('spare.request') and exists (
    select 1 from public.spare_requests r where r.uid = request_uid
      and (r.created_by = auth.uid() or public.is_admin())));
drop policy if exists srl_update on public.spare_request_lines;
create policy srl_update on public.spare_request_lines for update
  using (public.can_approve_spares()) with check (public.can_approve_spares());

-- ---------------------------------------------------------------------------
-- Approval-stage guard. RLS grants or denies a whole row, so it cannot say
-- "you may set rm_approval but not nsm_approval". This trigger does: each
-- stage's columns may only change if the user holds that stage's action.
-- ---------------------------------------------------------------------------
create or replace function public.spare_requests_stage_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  changed boolean;
begin
  if public.is_admin() then return new; end if;

  changed := new.rm_approval is distinct from old.rm_approval
          or new.rm_by       is distinct from old.rm_by
          or new.rm_at       is distinct from old.rm_at;
  if changed and not public.has_perm('spare.approve_rm') then
    raise exception 'RBAC: RM approval requires the spare.approve_rm permission';
  end if;

  changed := new.commercial_approval is distinct from old.commercial_approval
          or new.commercial_by       is distinct from old.commercial_by
          or new.commercial_at       is distinct from old.commercial_at;
  if changed and not public.has_perm('spare.approve_commercial') then
    raise exception 'RBAC: Commercial approval requires the spare.approve_commercial permission';
  end if;

  changed := new.nsm_approval is distinct from old.nsm_approval
          or new.nsm_by       is distinct from old.nsm_by
          or new.nsm_at       is distinct from old.nsm_at;
  if changed and not public.has_perm('spare.approve_nsm') then
    raise exception 'RBAC: NSM approval requires the spare.approve_nsm permission';
  end if;

  changed := new.stores_status  is distinct from old.stores_status
          or new.dc_number      is distinct from old.dc_number
          or new.dispatched_by  is distinct from old.dispatched_by
          or new.dispatched_at  is distinct from old.dispatched_at;
  if changed and not public.has_perm('spare.dispatch') then
    raise exception 'RBAC: dispatch / DC requires the spare.dispatch permission';
  end if;

  -- The workflow stage itself only moves as a side effect of an approval.
  if new.stage is distinct from old.stage and not public.can_approve_spares() then
    raise exception 'RBAC: advancing the approval stage requires an approval permission';
  end if;

  return new;
end $$;

drop trigger if exists spare_requests_stage_guard on public.spare_requests;
create trigger spare_requests_stage_guard
  before update on public.spare_requests
  for each row execute function public.spare_requests_stage_guard();

-- ---------------------------------------------------------------------------
-- Nobody edits their own role or extra permissions (privilege escalation) —
-- only users.manage may, and never to grant admin unless already an admin.
-- ---------------------------------------------------------------------------
create or replace function public.profiles_role_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.role is distinct from old.role or new.extra_permissions is distinct from old.extra_permissions then
    if new.id = auth.uid() and not public.is_super_admin() then
      raise exception 'RBAC: you cannot change your own role or permissions';
    end if;
  end if;
  if new.role is distinct from old.role
     and lower(new.role) = 'admin' and not public.is_admin() then
    raise exception 'RBAC: granting admin requires an administrator';
  end if;
  return new;
end $$;

drop trigger if exists profiles_role_guard on public.profiles;
create trigger profiles_role_guard
  before update on public.profiles
  for each row execute function public.profiles_role_guard();

-- ------------------------------------------------------------------------
-- 0013_all_masters_module.sql
-- ------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- 0013 — All Masters module access.
--
-- The new /masters screen (every master the app reads, with its source, size
-- and values) is gated like any other module by `mod:/masters`. 0008 seeded the
-- role matrix with the modules that existed then and deliberately leaves an
-- existing role's permissions alone, so the new key is on no role. Append it —
-- additively — to every role that can already open a master register
-- (`mod:/parts`), without disturbing any permission an admin has since edited.
-- ---------------------------------------------------------------------------
update public.app_roles
   set permissions = coalesce(permissions, '[]'::jsonb) || '["mod:/masters"]'::jsonb,
       updated_at  = now()
 where coalesce(permissions, '[]'::jsonb) ? 'mod:/parts'
   and not coalesce(permissions, '[]'::jsonb) ? 'mod:/masters';

-- ------------------------------------------------------------------------
-- 0030_engineer_address_write.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Who may set an engineer's delivery address.
--
-- The columns are the User Master's (0029_engineer_address.sql). This is only
-- the rule about writing them, and it ships with RBAC because its policy calls
-- has_perm(), which RBAC defines and which applies after the User Directory.
--
-- Writing them is deliberately NOT admin-only. The person who finds out an
-- address is wrong is the one packing the parcel, so anyone who can dispatch
-- may correct it — and ONLY it: the guard refuses every other column from a
-- non-admin, so the reporting tree (which drives who can see whose calls)
-- cannot be edited through this door.
-- ===========================================================================

create or replace function public.user_directory_address_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if public.is_admin() then return new; end if;
  -- Everything except the four address fields must be identical.
  if new.id                is distinct from old.id
  or new.name              is distinct from old.name
  or new.email             is distinct from old.email
  or new.gmail             is distinct from old.gmail
  or new.designation       is distinct from old.designation
  or new.reporting_manager is distinct from old.reporting_manager
  or new.regional_manager  is distinct from old.regional_manager
  or new.region            is distinct from old.region
  or new.validity          is distinct from old.validity
  or new.extra             is distinct from old.extra then
    raise exception 'Only an administrator may edit the user directory; dispatch may set the address only';
  end if;
  if not public.has_perm('spare.dispatch') then
    raise exception 'RBAC: setting a delivery address requires the spare.dispatch permission';
  end if;
  return new;
end $$;

drop trigger if exists user_directory_address_guard on public.user_directory;
create trigger user_directory_address_guard
  before update on public.user_directory
  for each row execute function public.user_directory_address_guard();

-- The policy lets a dispatcher through; the guard above decides what they may
-- actually change. (0004's ud_admin_write still covers admins for everything.)
drop policy if exists ud_address_update on public.user_directory;
create policy ud_address_update on public.user_directory for update
  using (public.is_admin() or public.has_perm('spare.dispatch'))
  with check (public.is_admin() or public.has_perm('spare.dispatch'));

-- ------------------------------------------------------------------------
-- 0033_user_directory_role.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- The role a User Master row carries, and the profile it becomes.
--
-- Roles live on `profiles`, which only exists once a person has signed in — so
-- until now a new joiner could not be given a role in advance, and someone who
-- had never signed in could not be seen or edited anywhere in the app. The
-- User Master is where people are actually maintained, so the role belongs
-- there too:
--
--   • `user_directory.role` is the role to grant, set by an administrator on
--     the User Master screen.
--   • `ensure_my_profile()` turns that into a real profile the first time the
--     person signs in — name, designation and role taken from their directory
--     row, so they arrive with the access they were given rather than as a
--     bare engineer.
--
-- Changing the role of someone who has already signed in is a `profiles` edit
-- (User Access, or the same screen) — this only decides where a profile starts.
-- ===========================================================================

alter table public.user_directory add column if not exists role text default '';

comment on column public.user_directory.role is
  'RBAC role key (app_roles.role) granted when this person first signs in.';

-- ---------------------------------------------------------------------------
-- The address guard (0030_engineer_address_write.sql) lets a dispatcher fix an
-- address and nothing else. `role` is new, so it has to join the list of
-- columns they must leave alone — otherwise the door meant for an address
-- would hand out permissions.
-- ---------------------------------------------------------------------------
create or replace function public.user_directory_address_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if public.is_admin() then return new; end if;
  -- Everything except the four address fields must be identical.
  if new.id                is distinct from old.id
  or new.name              is distinct from old.name
  or new.email             is distinct from old.email
  or new.gmail             is distinct from old.gmail
  or new.designation       is distinct from old.designation
  or new.reporting_manager is distinct from old.reporting_manager
  or new.regional_manager  is distinct from old.regional_manager
  or new.region            is distinct from old.region
  or new.validity          is distinct from old.validity
  or new.role              is distinct from old.role
  or new.extra             is distinct from old.extra then
    raise exception 'Only an administrator may edit the user directory; dispatch may set the address only';
  end if;
  if not public.has_perm('spare.dispatch') then
    raise exception 'RBAC: setting a delivery address requires the spare.dispatch permission';
  end if;
  return new;
end $$;

-- ---------------------------------------------------------------------------
-- First sign-in: build the profile from the User Master row.
--
-- Nothing created a `profiles` row, so a person who signed in without one was
-- shown as a bare engineer and never appeared in User Access — invisible to
-- the very screen that assigns roles. This closes that: it runs for the caller
-- only (auth.uid()), and takes the role from their directory row.
--
-- SECURITY DEFINER, so the caller does not need write access to profiles; the
-- role it grants is whatever an administrator put on the directory row, and
-- only if the role matrix actually knows it — a typo grants nothing rather
-- than something unintended.
-- ---------------------------------------------------------------------------
create or replace function public.ensure_my_profile()
returns public.profiles language plpgsql security definer set search_path = public as $$
declare
  me   uuid := auth.uid();
  mail text := lower(coalesce(auth.email(), ''));
  dir  public.user_directory;
  p    public.profiles;
  want text;
begin
  if me is null then return null; end if;

  select * into p from public.profiles where id = me;
  if found then return p; end if;

  select * into dir from public.user_directory
   where lower(email) = mail or lower(gmail) = mail
   limit 1;

  want := nullif(btrim(coalesce(dir.role, '')), '');
  if want is not null and not exists (select 1 from public.app_roles where role = want) then
    want := null;  -- not a role the matrix knows: fall back rather than guess
  end if;

  insert into public.profiles (id, email, full_name, role, designation, active)
  values (
    me,
    coalesce(auth.email(), ''),
    coalesce(nullif(btrim(coalesce(dir.name, '')), ''), coalesce(auth.email(), '')),
    coalesce(want, 'engineer'),
    coalesce(dir.designation, ''),
    coalesce(dir.validity, true)
  )
  on conflict do nothing;   -- id or email already taken: leave what is there

  select * into p from public.profiles where id = me;
  return p;   -- null if the email belongs to another profile; the caller copes
end $$;

revoke all on function public.ensure_my_profile() from public;
grant execute on function public.ensure_my_profile() to authenticated;

-- ------------------------------------------------------------------------
-- 0034_office_roles_see_all.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Office / coordination roles see every call.
-- Hotline, NSM, Commercial, Spare Coordinator, Stores Incharge and Tally
-- Coordinator are not tied to a call's allocation, so they should see all calls
-- (and, through the policies that reuse can_see_call, all reports / spares).
-- Engineers, RMs and RGMs stay scoped to their own / their sub-tree's calls.
-- ===========================================================================

-- True when the signed-in user's role is an office/coordination role (or admin).
create or replace function public.can_view_all_calls()
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_admin() or exists (
    select 1 from public.profiles p
     where p.id = auth.uid()
       and lower(coalesce(p.role, '')) in
           ('hotline', 'nsm', 'commercial', 'spare_coordinator', 'stores_incharge', 'tally_coordinator')
  );
$$;
grant execute on function public.can_view_all_calls() to authenticated;

-- Fold the new bypass into can_see_call (used by calls / reports / spare policies).
create or replace function public.can_see_call(allottee text)
returns boolean language sql stable security definer set search_path = public as $$
  select public.can_view_all_calls()
      or coalesce(allottee, '') = ''
      or lower(trim(allottee)) in (
           select lower(trim(n)) from public.visible_engineer_names() as v(n)
         );
$$;

-- ------------------------------------------------------------------------
-- 0035_data_view_all.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- data.view_all — a per-user (or per-role) grant for FULL data visibility, used
-- by a "Permissions + Data" clone. Folded into the read paths so the holder
-- sees every call, spare request/line, report and consumption row.
-- ===========================================================================

-- Calls / reports (reports read via can_see_call).
create or replace function public.can_view_all_calls()
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_admin()
      or public.has_perm('data.view_all')
      or exists (
        select 1 from public.profiles p
         where p.id = auth.uid()
           and lower(coalesce(p.role, '')) in
               ('hotline', 'nsm', 'commercial', 'spare_coordinator', 'stores_incharge', 'tally_coordinator')
      );
$$;

-- Spare requests (lines read follows the request).
drop policy if exists sr_read on public.spare_requests;
create policy sr_read on public.spare_requests for select
  using (public.is_admin() or public.has_perm('data.view_all') or created_by = auth.uid()
    or lower(engineer_email) = lower(auth.email())
    or public.can_approve_spares()
    or lower(trim(engineer)) in (select lower(trim(n)) from public.visible_engineer_names() as v(n)));

-- Consumption.
drop policy if exists cons_read on public.spare_consumption;
create policy cons_read on public.spare_consumption for select
  using (public.has_perm('consumption.view') or public.has_perm('data.view_all'));

-- ------------------------------------------------------------------------
-- 0037_call_read_scale.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Calls / reports read at scale — stop re-deriving the reporting tree per row.
--
-- can_see_call(allottee) wraps `allottee in (select ... visible_engineer_names())`
-- in a scalar function that takes the per-row allocation as its argument. Because
-- the argument changes per row, the planner treats the whole function as a black
-- box and evaluates it — including the RECURSIVE tree walk inside
-- visible_engineer_names() — once for EVERY call row. At 15–18k PM calls a year
-- (and their reports) that is "canceling statement due to statement timeout" on
-- Pending Calls and Reports. 0014 removed this cost once; 0034 folding the office
-- bypass back through can_see_call reintroduced it.
--
-- The fix is not new logic, only new SHAPE: inline the visibility test into the
-- policy so the tree set is an uncorrelated sub-select — an InitPlan Postgres
-- builds ONCE per query and hash-probes per row — and wrap the no-arg auth
-- helpers in (select …) so they are evaluated once too (the Supabase RLS
-- performance pattern). Same rows are visible to the same people; only the plan
-- changes. can_see_call() itself is left in place for callers not on the hot path.
-- ===========================================================================

-- ---- calls: read + update --------------------------------------------------
do $calls_guard$ begin
-- 0040_call_tables_split.sql replaces public.calls with a VIEW over the three
-- typed call tables. What follows is table-only work, so on a project that has
-- already been split it has to be SKIPPED, not attempted — otherwise replaying
-- this file (which re-running any bundle does) dies with
--   ERROR 42809: cannot create index on relation "calls"
-- or "calls is not a table". On an unsplit project it runs exactly as before.
if (select c.relkind from pg_class c join pg_namespace n on n.oid = c.relnamespace
     where n.nspname = 'public' and c.relname = 'calls') = 'r' then
execute $calls_sql$
drop policy if exists calls_scoped_read on public.calls;
create policy calls_scoped_read on public.calls for select
  using (
    (select public.has_perm('calls.view'))
    and (
      (select public.can_view_all_calls())
      or created_by = (select auth.uid())
      or coalesce(allocated_to, '') = ''
      or lower(trim(allocated_to)) in (
           select lower(trim(n)) from public.visible_engineer_names() as v(n)
         )
    )
  );

drop policy if exists calls_update on public.calls;
create policy calls_update on public.calls for update
  using (
    (select (public.has_perm('calls.edit') or public.has_perm('calls.report')))
    and (
      (select public.can_view_all_calls())
      or created_by = (select auth.uid())
      or coalesce(allocated_to, '') = ''
      or lower(trim(allocated_to)) in (
           select lower(trim(n)) from public.visible_engineer_names() as v(n)
         )
    )
  )
  with check (
    (select (public.has_perm('calls.edit') or public.has_perm('calls.report')))
    and (
      (select public.can_view_all_calls())
      or created_by = (select auth.uid())
      or coalesce(allocated_to, '') = ''
      or lower(trim(allocated_to)) in (
           select lower(trim(n)) from public.visible_engineer_names() as v(n)
         )
    )
  );
$calls_sql$;
end if;
end $calls_guard$;-- ---- reports: read (visible with the parent call) --------------------------
-- The recursive set is uncorrelated, so it stays an InitPlan (once); the only
-- per-report work is the indexed lookup of its call by ucn.
drop policy if exists reports_read on public.reports;
create policy reports_read on public.reports for select
  using (
    (select public.is_admin())
    or (
      (select public.has_perm('calls.view'))
      and (
        (select public.can_view_all_calls())
        or exists (
          select 1 from public.calls c
           where c.ucn = reports.ucn
             and (
               coalesce(c.allocated_to, '') = ''
               or lower(trim(c.allocated_to)) in (
                    select lower(trim(n)) from public.visible_engineer_names() as v(n)
                  )
             )
        )
      )
    )
  );

-- ------------------------------------------------------------------------
-- 0051_pending_registrations_view_all.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Hotline (and the office roles) must see the WHOLE pending-registration queue,
-- not just their own requests — that queue is the Hotline's work: map each to a
-- call, register a new one, or cancel it. The pend_read policy (0008) only let a
-- user see their own rows or an engineer in their reporting sub-tree, so a
-- Hotline engineer (who has no sub-tree) saw almost none.
--
-- Fold in can_view_all_calls() (0035) — is_admin, data.view_all, and the roles
-- hotline / nsm / commercial / spare_coordinator / stores_incharge /
-- tally_coordinator — exactly as the call register already does. The whole call
-- register is already visible to those roles (0037 / 0040); this brings the
-- pending queue in line.
-- ===========================================================================

drop policy if exists pend_read on public.pending_registrations;
create policy pend_read on public.pending_registrations for select
  using (
    public.can_view_all_calls()              -- admin, data.view_all, Hotline + office roles: the whole queue
    or created_by = auth.uid()               -- your own requests
    or (public.has_perm('calls.view')        -- a manager: requests for an engineer in their reporting sub-tree
        and lower(trim(engineer)) in (select lower(trim(n)) from public.visible_engineer_names() as v(n)))
  );

-- ------------------------------------------------------------------------
-- 0069_nsm_service_manager.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- NSM is the National SERVICE Manager, not the National Sales Manager.
--
-- 0008 seeded the label, and its upsert deliberately keeps a label an admin has
-- already set (`coalesce(nullif(existing.label,''), excluded.label)`) — so
-- correcting the seed does nothing to a project where the row already exists.
-- This corrects the stored label in place, and ONLY that exact wording, so a
-- name an admin chose themselves is left alone.
-- ===========================================================================

do $$
begin
  if to_regclass('public.app_roles') is null then
    raise notice 'public.app_roles is not present — run the rbac bundle first';
    return;
  end if;

  update public.app_roles
     set label = 'NSM (National Service Manager)', updated_at = now()
   where role = 'nsm'
     and label = 'NSM (National Sales Manager)';
end $$;

-- ------------------------------------------------------------------------
-- 0093_lookup_module.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- The Product & Party Search screen, for whoever already has the Product Master.
--
-- A new module is in the code's defaults, but `has_perm` reads the STORED list
-- on `app_roles` and only falls back to those defaults when the row is empty —
-- so a role that has ever been saved in Roles & Permissions would not see the
-- screen at all. Granted here, by MERGING, so an administrator's other edits
-- are untouched.
--
-- The rule is simple: it reads exactly what Product Master reads — the install
-- base and the party it belongs to — from the other end. Anyone who may open
-- one may open the other. No new data is exposed, and row-level security
-- answers for the rows either way.
-- ===========================================================================

update public.app_roles
   set permissions = coalesce(permissions, '[]'::jsonb) || '["mod:/lookup"]'::jsonb,
       updated_at  = now()
 where (role = 'admin' or coalesce(permissions, '[]'::jsonb) ? 'mod:/product-master')
   and not coalesce(permissions, '[]'::jsonb) ? 'mod:/lookup';

-- ------------------------------------------------------------------------
-- 0110_admin_reset_password.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- AN ADMINISTRATOR CAN RESET A FORGOTTEN PASSWORD.
--
-- The sign-in page now says "ask an administrator" (v0.9.89), and until this
-- there was nothing for the administrator to do — they had to go to the
-- Supabase dashboard. This gives them the action in the app: a random password
-- is generated, set on the account, and shown ONCE so it can be passed to the
-- person, who changes it under Profile → Password whenever they like.
--
-- WHY IT WRITES `auth.users` DIRECTLY, AND WHAT THAT COSTS.
-- Setting somebody ELSE'S password is an admin-API operation, and the admin API
-- needs the service_role key — which must never be in a browser, so the app
-- cannot call it. The two honest options were an Edge Function holding that key
-- or a definer function here. This project delivers everything as a migration
-- the user runs, and an admin action that fails until an Edge Function is
-- deployed is an admin action that does not work. So: here, as SECURITY
-- DEFINER, writing the same bcrypt hash Supabase's own reset writes.
--
-- It is off the supported path, and these are the limits:
--   • it does not run Supabase's own password policy — the length floor below
--     is the only rule, and the generator makes far longer ones;
--   • it does not send anything. The administrator passes the password on;
--   • if Supabase ever changes how it stores passwords this stops working, and
--     it stops LOUDLY (the person cannot sign in), not silently.
--
-- WHAT IT REFUSES:
--   • anyone who is not an administrator;
--   • a super admin's account, unless the caller is a super admin. An admin who
--     could reset a super admin's password could take the project;
--   • a password under 10 characters, so this cannot be used to set a weak one.
--
-- THE PASSWORD IS NEVER STORED. `password_resets` records WHO reset WHOSE
-- account and when — the fact of it, which is what an audit needs — and nothing
-- that could be used to sign in.
--
-- Every session the person had is ended, so a reset actually takes effect
-- everywhere rather than leaving an old phone signed in.
-- ===========================================================================

create extension if not exists pgcrypto;

create table if not exists public.password_resets (
  id             bigint generated always as identity primary key,
  target_email   text not null,
  target_id      uuid,
  reset_by       uuid,
  reset_by_email text not null default '',
  reset_at       timestamptz not null default now()
);
create index if not exists password_resets_at_idx on public.password_resets (reset_at desc);

alter table public.password_resets enable row level security;
-- Readable by administrators, written only by the function below (which is
-- definer, so it is not subject to this).
drop policy if exists pwr_read on public.password_resets;
create policy pwr_read on public.password_resets for select using (public.is_admin());

create or replace function public.admin_reset_password(p_email text, p_password text)
returns text language plpgsql security definer
set search_path = public, extensions, auth as $$
declare v_id uuid; v_email text; v_target_super boolean;
begin
  if not public.is_admin() then
    raise exception 'RBAC: only an administrator can reset a password';
  end if;
  -- The generator makes 14; this floor is here so the function cannot be used
  -- to set something weak by hand.
  if length(coalesce(p_password, '')) < 10 then
    raise exception 'A reset password must be at least 10 characters';
  end if;

  v_email := lower(btrim(coalesce(p_email, '')));
  select u.id into v_id from auth.users u where lower(u.email) = v_email;
  if v_id is null then raise exception 'No login for %', p_email; end if;

  select exists (select 1 from public.app_super_admins s where lower(s.email) = v_email)
    into v_target_super;
  if v_target_super and not public.is_super_admin() then
    raise exception 'Only a super admin can reset a super admin''s password';
  end if;

  update auth.users
     set encrypted_password = crypt(p_password, gen_salt('bf')),
         updated_at         = now()
   where id = v_id;

  -- End what they had open, so the reset takes effect on every device rather
  -- than leaving an old session signed in. Both tables are Supabase's own and
  -- absent from a bare Postgres, so neither is allowed to fail the reset.
  begin
    delete from auth.sessions where user_id = v_id;
  exception when others then null;
  end;
  begin
    delete from auth.refresh_tokens where user_id::text = v_id::text;
  exception when others then null;
  end;

  insert into public.password_resets (target_email, target_id, reset_by, reset_by_email)
  values (v_email, v_id, auth.uid(), coalesce(auth.email(), ''));

  return v_email;
end $$;
revoke all on function public.admin_reset_password(text, text) from public;
grant execute on function public.admin_reset_password(text, text) to authenticated;

-- ------------------------------------------------------------------------
-- 0120_role_table_views.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- A TABLE'S LAYOUT, SET FOR A ROLE.
--
-- The user's ask (2026-09-06): "like save for everyone, I need option to set
-- the views to roles."
--
-- What a register looks like — which columns, in what order, how wide, grouped
-- by what, filtered how — is currently each person's own, kept in their
-- browser. There is also a "default for everyone", but it goes through the
-- Apps Script sheet bridge, it is all-or-nothing, and it carries only the
-- columns: not the grouping, not the filters. Nobody can say "this is how the
-- Stores In-charge should see Pending Dispatch".
--
-- So: one row per (register, role), holding the whole layout. A role of '' is
-- EVERYONE — the same table answers both questions rather than one mechanism
-- for roles and a different one for all, which would drift.
--
-- WHOSE LAYOUT WINS. The same rule as the Auto Save default, and for the same
-- reason: both the reader's own arrangement and the administrator's carry a
-- TIME, and the later decision stands. "The admin always wins" would make
-- every reader's column picker a lie; "your own always wins" would make
-- "apply to a role" a lie. `set_at` is what the client compares against.
--
-- ADMIN-ONLY WRITE, everyone reads. A layout is not sensitive — it says which
-- columns to show, not what is in them — and RLS on the underlying registers
-- is what decides the rows either way.
-- ===========================================================================

create table if not exists public.role_table_views (
  storage_key text        not null,
  role        text        not null default '',     -- '' = everyone
  view        jsonb       not null default '{}'::jsonb,
  set_at      bigint      not null default (extract(epoch from now()) * 1000)::bigint,
  updated_at  timestamptz not null default now(),
  updated_by  uuid        references auth.users (id),
  primary key (storage_key, role)
);

comment on table public.role_table_views is
  'How a register looks for a role: columns, order, widths, grouping, filters. role = '''' means everyone. set_at is compared against the reader''s own arrangement — the later decision wins.';

alter table public.role_table_views enable row level security;
grant select on public.role_table_views to authenticated;
revoke insert, update, delete on public.role_table_views from authenticated;

drop policy if exists rtv_read on public.role_table_views;
create policy rtv_read on public.role_table_views for select
  using (auth.role() = 'authenticated');

-- Writes go through the function below, so the rule about WHO can set a
-- layout lives in one place and `set_at` cannot be back-dated by a caller.
drop policy if exists rtv_write on public.role_table_views;
create policy rtv_write on public.role_table_views for all
  using (public.is_admin() or public.has_perm('config.manage'))
  with check (public.is_admin() or public.has_perm('config.manage'));

create or replace function public.set_role_table_view(
  p_storage_key text, p_role text, p_view jsonb
) returns bigint
language plpgsql security definer set search_path = public as $$
declare v_at bigint := (extract(epoch from now()) * 1000)::bigint;
begin
  if not (public.is_admin() or public.has_perm('config.manage')) then
    raise exception 'RBAC: only an administrator can set a layout for a role';
  end if;
  if coalesce(btrim(p_storage_key), '') = '' then
    raise exception 'Which register?';
  end if;

  insert into public.role_table_views (storage_key, role, view, set_at, updated_at, updated_by)
  values (btrim(p_storage_key), coalesce(btrim(p_role), ''), coalesce(p_view, '{}'::jsonb), v_at, now(), auth.uid())
  on conflict (storage_key, role) do update
     set view = excluded.view, set_at = excluded.set_at,
         updated_at = excluded.updated_at, updated_by = excluded.updated_by;

  return v_at;
end $$;
revoke all on function public.set_role_table_view(text, text, jsonb) from public;
grant execute on function public.set_role_table_view(text, text, jsonb) to authenticated;

-- Clearing one is a decision too, and it must be possible without inventing an
-- "empty layout" that would read as "show no columns".
create or replace function public.clear_role_table_view(p_storage_key text, p_role text)
returns boolean language plpgsql security definer set search_path = public as $$
begin
  if not (public.is_admin() or public.has_perm('config.manage')) then
    raise exception 'RBAC: only an administrator can clear a layout for a role';
  end if;
  delete from public.role_table_views
   where storage_key = btrim(p_storage_key) and role = coalesce(btrim(p_role), '');
  return found;
end $$;
revoke all on function public.clear_role_table_view(text, text) from public;
grant execute on function public.clear_role_table_view(text, text) to authenticated;

-- WHICH LAYOUT APPLIES TO THE CALLER: the one set for their role, and failing
-- that the one set for everyone. Resolved in the database so every register
-- asks the question the same way and a role name is never matched in the
-- browser against a role the browser only thinks it has.
create or replace function public.my_table_view(p_storage_key text)
returns table (view jsonb, set_at bigint, role text)
language sql stable security definer set search_path = public as $$
  select v.view, v.set_at, v.role
    from public.role_table_views v
   where v.storage_key = btrim(p_storage_key)
     and (v.role = '' or v.role = coalesce(public.my_role(), ''))
   order by (v.role <> '') desc      -- the role's own beats the everyone one
   limit 1
$$;
revoke all on function public.my_table_view(text) from public;
grant execute on function public.my_table_view(text) to authenticated;

-- ------------------------------------------------------------------------
-- 0087_spare_line_stub_rls.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- "Your role does not have permission for this action." on the FIRST spare line.
--
-- 0084 lets a line whose request is in neither export create a stub parent from
-- a BEFORE INSERT trigger, so one gap in the source does not cost the file. The
-- foreign key is satisfied by that stub — referential checks run at the end of
-- the statement, with a fresh snapshot — but `srl_insert` is NOT:
--
--   with check (has_perm('spare.request') and exists (
--     select 1 from spare_requests r where r.uid = request_uid
--       and (r.created_by = auth.uid() or is_admin())))
--
-- A row-level security check is evaluated INSIDE the inserting command, and a
-- command cannot see rows written by SQL its own triggers ran: the stub's cmin
-- is higher than the command's. So the EXISTS finds nothing and the row is
-- refused — for an ADMIN too, because `is_admin()` sat inside the EXISTS and an
-- EXISTS with no row is false however permissive its predicate is.
--
-- And PostgREST sends the whole upload as ONE insert, so a single such line
-- fails all 8,571 — which is what happened on row 1 (OR26724, an OR number the
-- 2026 header export does not go back far enough to carry).
--
-- Hoisting `is_admin()` out of the EXISTS is the whole fix. It takes nothing
-- away from anyone else: a non-admin still has to own the request they are
-- attaching lines to, and an admin could already read and write every one of
-- these rows.
-- ===========================================================================

drop policy if exists srl_insert on public.spare_request_lines;
create policy srl_insert on public.spare_request_lines for insert
  with check (
    public.has_perm('spare.request')
    and (
      public.is_admin()
      or exists (
        select 1 from public.spare_requests r
         where r.uid = request_uid and r.created_by = auth.uid())
    ));

-- ------------------------------------------------------------------------
-- 0088_spare_line_parent_visible.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- "Your role does not have permission for this action." on the first spare
-- line — still, after 0087.
--
-- 0087 hoisted `is_admin()` out of the EXISTS, which fixes the upload for an
-- administrator and nobody else. But the real fault is not WHO is uploading, it
-- is that the check cannot SEE what it is checking: 0084's stub parent is
-- written by a BEFORE trigger, and a command cannot see rows the SQL its own
-- triggers ran has inserted. So for anyone who is not an admin — a Spare
-- Coordinator, an RM, whoever actually loads the register — the row is still
-- refused, and one such line still fails all 8,571.
--
-- Ask the question in a place that can see the answer. A VOLATILE plpgsql
-- function takes a FRESH SNAPSHOT for each statement it runs (read committed),
-- so the stub its caller's trigger just wrote is visible to it. Same question,
-- same rule — a line must belong to a request you raised (or you are an
-- admin) — asked where it can be answered truthfully.
--
-- It is SECURITY DEFINER so the lookup is not itself filtered by `sr_read`
-- (a request you own but cannot yet read would otherwise answer "no"), and it
-- returns a BOOLEAN and nothing else, so it discloses nothing.
-- ===========================================================================

create or replace function public.spare_line_parent_ok(p_uid text)
returns boolean language plpgsql volatile security definer set search_path = public as $$
declare ok boolean;
begin
  if btrim(coalesce(p_uid, '')) = '' then
    return false;                                 -- no parent named; the FK will say so
  end if;
  select exists (
    select 1 from public.spare_requests r
     where r.uid = p_uid
       and (r.created_by = auth.uid() or public.is_admin())
  ) into ok;
  return coalesce(ok, false);
end $$;

grant execute on function public.spare_line_parent_ok(text) to authenticated;

drop policy if exists srl_insert on public.spare_request_lines;
create policy srl_insert on public.spare_request_lines for insert
  with check (
    public.has_perm('spare.request')
    and public.spare_line_parent_ok(request_uid)
  );

-- ------------------------------------------------------------------------
-- 0145_technical_support_role.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- TECHNICAL SUPPORT — the Super Admin's reach, none of its writes.
--
-- The user, 2026-09-08: "Create a New Role 'Technical Support' - Map this Role
-- to All Modules and Mimic Super Admin - But with Read Only For now."
--
-- So the role holds EVERY module key, including the administration ones, and
-- exactly the actions that only READ. It is not a narrower admin: it is the
-- same field of view with nothing that changes a row.
--
-- WHAT MAKES IT READ-ONLY IS WHAT IT DOES NOT HOLD, not a flag. Every write in
-- this database is gated by an RLS policy naming the action it needs --
-- `calls.edit`, `masters.edit`, `spare.dispatch`, `users.manage`, and the rest.
-- A role holding none of them cannot write, whatever a screen offers it: the
-- refusal is Postgres's, not the browser's. That is also why the list below is
-- written out rather than filtered by a pattern -- `consumption.reconcile` and
-- `ownership.transfer` do not say "edit" either, and a rule that went by the
-- key's spelling would hand over both.
--
-- `data.view_all` is what makes the rest of it useful. Without it the role can
-- open every page and, on the call pages, sees only rows allotted to it --
-- which for a support login is nothing at all. can_view_all_calls() (0035)
-- already honours the permission, so no policy changes here.
--
-- `admin.view` is new: it opens the administration screens read-only. They
-- gated themselves on `users.manage` / `rbac.manage` -- the rights to CHANGE
-- what is on them -- so until now there was no way to let somebody look.
--
-- MERGED, NEVER OVERWRITTEN, like every other grant in this project: an
-- administrator may have tuned the role by the time this is replayed, and the
-- merge cannot widen it past read-only because nothing in the list writes.
-- ===========================================================================

do $ts$
declare
  -- Every module in src/lib/rbac.ts MODULES, admin ones included. Kept as a
  -- literal list because the database has no other record of what the app's
  -- pages are; a page added later is added here too (and the union below means
  -- anything the admin role has gained meanwhile comes along by itself).
  all_mods text[] := array[
    'mod:/','mod:/lookup','mod:/daily-review','mod:/parties','mod:/product-master',
    'mod:/user-master','mod:/parts','mod:/masters','mod:/service-manuals','mod:/qms',
    'mod:/warranties','mod:/contracts','mod:/ownership-transfer','mod:/request-registration',
    'mod:/pending-registrations','mod:/field-calls','mod:/installations','mod:/pm-calls',
    'mod:/pending-calls','mod:/reports','mod:/report-mapping','mod:/bulk-uploads',
    'mod:/spare-requests','mod:/spare-rm-approval','mod:/spare-dispatch','mod:/spare-consumption',
    'mod:/handstock','mod:/mrn','mod:/stock-transfer','mod:/feedback','mod:/failure-report',
    'mod:/kpi','mod:/objective','mod:/exports','mod:/tracker','mod:/users','mod:/roles',
    'mod:/audit','mod:/admin-config','mod:/settings','mod:/version-history'];
  -- READ ONLY. Nothing here changes a row.
  read_only text[] := array[
    'calls.view','masters.view','consumption.view','reports.view','dashboard.view',
    'feedback.view','audit.view','admin.view','export.data','data.view_all'];
  granted jsonb;
begin
  if to_regclass('public.app_roles') is null then
    raise notice 'app_roles is missing -- run rbac.sql first';
    return;
  end if;

  -- The module keys the ADMIN role actually holds, so a page added to the admin
  -- role by a later migration reaches Technical Support without this file being
  -- edited. Union, not replacement: the literal list above is the floor.
  select coalesce(jsonb_agg(distinct v), '[]'::jsonb) into granted
    from (
      select unnest(all_mods) as v
      union
      select unnest(read_only)
      union
      select m.v
        from public.app_roles ar,
             lateral jsonb_array_elements_text(ar.permissions) as m(v)
       where ar.role = 'admin'
         and m.v like 'mod:%'
    ) u;

  if exists (select 1 from public.app_roles r where r.role = 'technical_support') then
    -- MERGE. Whatever an administrator has since ticked stays ticked, and the
    -- merge cannot widen the role past read-only because nothing in `granted`
    -- writes.
    update public.app_roles r
       set permissions = (
             select coalesce(jsonb_agg(distinct v), '[]'::jsonb)
               from (
                 select e.v from jsonb_array_elements_text(r.permissions) as e(v)
                 union
                 select g.v from jsonb_array_elements_text(granted) as g(v)
               ) m
           ),
           label      = coalesce(nullif(r.label, ''), 'Technical Support'),
           updated_at = now()
     where r.role = 'technical_support';
  else
    insert into public.app_roles (role, label, permissions)
    values ('technical_support', 'Technical Support', granted);
  end if;

  raise notice 'Technical Support: % permission(s) -- every module, read-only actions only',
    jsonb_array_length(granted);
end $ts$;

-- ---------------------------------------------------------------------------
-- ADMIN GETS `admin.view` TOO, so the matrix does not show the Super Admin
-- missing a right it obviously holds. is_admin() short-circuits has_perm(), so
-- this changes nothing about what an admin can do -- it keeps the row honest.
-- ---------------------------------------------------------------------------
update public.app_roles ar
   set permissions = (
         select coalesce(jsonb_agg(distinct v), '[]'::jsonb)
           from (
             select jsonb_array_elements_text(ar.permissions) as v
             union
             select 'admin.view' as v
           ) u
       ),
       updated_at = now()
 where ar.role = 'admin'
   and not (ar.permissions ? 'admin.view');

-- ------------------------------------------------------------------------
-- 0151_module_keys_catch_up.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- THE STORED ROLES CATCH UP WITH THE PAGES.
--
-- The user, 2026-09-09: "Update the Role & Permissions as per the Current List
-- of Pages , Actions."
--
-- A NEW PAGE IS INVISIBLE UNTIL A ROLE HOLDS ITS KEY, and that is the failure
-- this file fixes. `DEFAULT_PERMS` in the app is only a FALLBACK: it applies to
-- a role whose `app_roles` row is empty. Every role here has a populated row,
-- so adding a module to the code grants it to nobody — the nav asks
-- `can('mod:/x')`, the stored list does not have it, and the page simply never
-- appears. No error, no clue.
--
-- Three keys were in exactly that state:
--
--   mod:/spare-insights      shipped yesterday and visible to NOBODY but an
--                            administrator (is_admin short-circuits has_perm).
--                            My omission, not a design.
--   mod:/pm-bulk-upload      a page in the menu that had never had a key at all.
--   mod:/software-validation the same.
--
-- WHO GETS WHAT, and why it is derived rather than listed:
--
--   * Spare Insights goes to every role that already holds `consumption.view`.
--     It is a consumption dashboard; the roles allowed to see consumption are
--     the roles allowed to see it summarised. Deriving it from the permission
--     rather than naming roles means an administrator who has already tuned a
--     role gets the answer their own tuning implies.
--   * The two admin pages go to `admin` -- and to `technical_support`, because
--     that role's whole definition is "every module key the admin role holds,
--     read-only" (0145). A new admin page that skipped it would break that
--     promise silently, which is the same class of bug as the three above.
--
-- MERGED, NEVER OVERWRITTEN. An administrator may have tuned any of these; the
-- merge only ever adds, and adds nothing that writes.
-- ===========================================================================

do $mods$
declare
  n int := 0;
begin
  if to_regclass('public.app_roles') is null then
    raise notice 'app_roles is missing -- run rbac.sql first';
    return;
  end if;

  -- ---- Spare Insights: wherever consumption is already visible -------------
  update public.app_roles ar
     set permissions = (
           select coalesce(jsonb_agg(distinct v), '[]'::jsonb)
             from (
               select jsonb_array_elements_text(ar.permissions) as v
               union select 'mod:/spare-insights'
             ) u
         ),
         updated_at = now()
   where ar.permissions ? 'consumption.view'
     and not (ar.permissions ? 'mod:/spare-insights');
  get diagnostics n = row_count;
  raise notice 'Spare Insights granted to % role(s) that already see consumption', n;

  -- ---- the two admin pages: admin, and the role defined as admin's reach ---
  update public.app_roles ar
     set permissions = (
           select coalesce(jsonb_agg(distinct v), '[]'::jsonb)
             from (
               select jsonb_array_elements_text(ar.permissions) as v
               union select unnest(array['mod:/pm-bulk-upload', 'mod:/software-validation'])
             ) u
         ),
         updated_at = now()
   where ar.role in ('admin', 'technical_support')
     and not (ar.permissions ?& array['mod:/pm-bulk-upload', 'mod:/software-validation']);
  get diagnostics n = row_count;
  raise notice 'PM Bulk Upload and Software Validation granted to % role(s)', n;

  -- ---- and Technical Support keeps its defining property -------------------
  -- "Every module key the admin role holds" is what that role IS. Rather than
  -- listing modules again here, take whatever the admin row actually carries --
  -- so this stays true for pages added after today as well, whenever this file
  -- is replayed.
  update public.app_roles ts
     set permissions = (
           select coalesce(jsonb_agg(distinct v), '[]'::jsonb)
             from (
               select jsonb_array_elements_text(ts.permissions) as v
               union
               select m.v from public.app_roles a,
                    lateral jsonb_array_elements_text(a.permissions) as m(v)
                where a.role = 'admin' and m.v like 'mod:%'
             ) u
         ),
         updated_at = now()
   where ts.role = 'technical_support';
end $mods$;

-- ------------------------------------------------------------------------
-- 0155_zoho_migration_role.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- ZOHO MIGRATION — Technical Support's twin, for as long as the migration runs.
--
-- The user, 2026-09-09: "Add one more Role called ZohoMigration, Use Technical
-- Support as the Cloning Role, Add this to all the Modules, Pages, Sub Pages,
-- Actions."
--
-- CLONED FROM THE STORED ROW, not from a copy of its list. 0145 had to write
-- its module list out by hand because nothing in the database knew what the
-- app's pages were; this one does not, because `technical_support` is already
-- sitting there holding the answer -- INCLUDING whatever an administrator has
-- ticked onto it since, and every page added after 0145 was written. A second
-- literal list would be a second thing to keep in step, and the two would
-- diverge the first time somebody edited one.
--
-- SUB-PAGES ARE GRANTED EXPLICITLY even though they would be INHERITED.
-- `parentAction()` already makes `mod:/exports` cover every report and
-- `mod:/masters` cover every value list, so the role would work without this.
-- But the ask names sub-pages, and Roles & Permissions shows a row per
-- sub-page: a screen where the boxes are empty and access nevertheless works
-- is a screen nobody can use to answer "what can this role open?". The master
-- lists are read from `masters` rather than listed, since they are data.
--
-- WHY A SEPARATE ROLE AT ALL, rather than pointing the migration at Technical
-- Support: this one ends when the migration does. Keeping them apart means
-- revoking it is one tick and leaves the support login untouched -- and the
-- audit trail says which of the two did a thing.
--
-- READ-ONLY, by the same mechanism as Technical Support and for the same
-- reason: every write in this database is gated by an RLS policy naming the
-- action it needs, and this role holds none of them. A migration reads
-- everything and writes nothing HERE -- what it writes goes into Zoho. The
-- refusal, if a screen ever offers it a button, is Postgres's and not the
-- browser's.
--
-- MERGED, NEVER OVERWRITTEN, like every grant in this project.
-- ===========================================================================

do $zm$
declare
  granted jsonb;
  n_mods  integer;
begin
  if to_regclass('public.app_roles') is null then
    raise notice 'app_roles is missing -- run rbac.sql first';
    return;
  end if;

  if not exists (select 1 from public.app_roles where role = 'technical_support') then
    -- The clone source has to exist. Inventing a fallback list here is how the
    -- two roles would end up differing, which is the one thing this file is
    -- built to prevent.
    raise notice 'technical_support is not there yet -- run 0145 (rbac.sql) first, then this';
    return;
  end if;

  select coalesce(jsonb_agg(distinct v), '[]'::jsonb) into granted
    from (
      -- 1. Everything Technical Support holds, as it stands right now.
      select m.v
        from public.app_roles ar, lateral jsonb_array_elements_text(ar.permissions) as m(v)
       where ar.role = 'technical_support'
      union
      -- 2. The report sub-pages, spelled out so the matrix shows them ticked.
      select unnest(array['mod:/exports/consumption','mod:/exports/kpi','mod:/exports/unused'])
      union
      -- 3. Every master value list that exists, same reason. Data, so derived.
      select 'mod:/masters/' || ml.name
        from (select distinct name from public.masters where coalesce(name,'') <> '') ml
    ) u;

  if exists (select 1 from public.app_roles r where r.role = 'zoho_migration') then
    update public.app_roles r
       set permissions = (
             select coalesce(jsonb_agg(distinct v), '[]'::jsonb)
               from (
                 select e.v from jsonb_array_elements_text(r.permissions) as e(v)
                 union
                 select g.v from jsonb_array_elements_text(granted) as g(v)
               ) m
           ),
           label      = coalesce(nullif(r.label, ''), 'Zoho Migration'),
           updated_at = now()
     where r.role = 'zoho_migration';
  else
    insert into public.app_roles (role, label, permissions)
    values ('zoho_migration', 'Zoho Migration', granted);
  end if;

  select count(*) into n_mods
    from jsonb_array_elements_text(granted) as e(v) where e.v like 'mod:%';

  raise notice 'Zoho Migration: % permission(s), % module/page key(s) -- cloned from Technical Support, read-only',
    jsonb_array_length(granted), n_mods;
end $zm$;

-- ------------------------------------------------------------------------
-- 0156_remove_super_admin_mmdev74.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- REVOKE A SUPER ADMIN.
--
-- The user, 2026-09-09: "mmdev74@gmail.com - remove him from Admin".
--
-- SUPER ADMIN IS TWO THINGS IN TWO PLACES and both have to go, or the account
-- keeps real access:
--
--   * `public.app_super_admins` -- what is_super_admin() reads, so what
--     POSTGRES allows. Removed here.
--   * `SUPER_ADMINS` in src/lib/auth.tsx -- what the BROWSER offers. Removed in
--     the same change; without it the screens still hand them every button and
--     the database quietly refuses each one, which reads as the app being
--     broken rather than as access having been withdrawn.
--
-- AND `profiles.role` IS A THIRD PLACE. is_admin() is `role = 'admin'` OR the
-- super-admin row -- so dropping only the row can leave an ordinary Admin
-- standing, which is not what "remove him from Admin" means. It is downgraded
-- below, and only if it currently says admin.
--
-- DOWNGRADED TO `engineer`, the system's own default for a login with no role
-- set, chosen because it is the least this codebase can express: there is no
-- "no access" ROLE. If the intent is that this person should not sign in AT
-- ALL, that is a different action -- set their User Master row inactive -- and
-- it is deliberately not assumed here. Revoking rights is safe to do without
-- asking; deciding somebody should be locked out entirely is not.
--
-- 0008 SEEDS THAT ROW, and this migration must stay AFTER it in the `rbac`
-- module. Replaying rbac.sql runs 0008's insert (which puts the address back)
-- and then this delete -- in that order, the account ends revoked. The other
-- order would silently restore a super admin on every bundle replay, which is
-- exactly the class of fault this project has been bitten by.
--
-- Idempotent, and it says what it did.
-- ===========================================================================

do $rm$
declare
  v_email text := 'mmdev74@gmail.com';
  n_super integer := 0;
  n_role  integer := 0;
begin
  delete from public.app_super_admins where lower(email) = lower(v_email);
  get diagnostics n_super = row_count;

  update public.profiles
     set role = 'engineer'
   where lower(email) = lower(v_email)
     and lower(coalesce(role, '')) = 'admin';
  get diagnostics n_role = row_count;

  raise notice 'Super admin revoked for %: % super-admin row(s) removed, % profile(s) downgraded from admin',
    v_email, n_super, n_role;

  if n_super = 0 and n_role = 0 then
    raise notice '  (nothing to do -- already revoked, or that address has no rows here)';
  end if;
end $rm$;

-- ------------------------------------------------------------------------
-- 0171_stock_out_module.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0171 — STOCK OUT IS A PAGE, so it needs a permission of its own.
--
-- The user, 2026-09-12: "Add a Separate Page as Stock Out - the same FlatList
-- under Pending Dispatch", and with it "Match the Roles and Permissions as per
-- the Re-arrangement."
--
-- The list was a TAB on Pending Dispatch, so the right to read it was the right
-- to open that queue — one key for two different questions. Splitting them is
-- the point of the move: Commercial chasing a DC and a Reporting Manager
-- checking what an engineer was sent both want the record of what WENT OUT, and
-- neither has any business in the Stores queue.
--
-- NOBODY LOSES ANYTHING TODAY. Every role that can open Pending Dispatch is
-- given the new key, so the tab they were reading yesterday is the page they
-- read tomorrow. From here on the two can be granted apart, which they could
-- not be before.
--
-- MERGED, NEVER OVERWRITTEN (CLAUDE.md, and the reason is in 0126): an
-- administrator may have tuned a role, and a grant that replaces the array
-- silently throws that away. `permissions ? 'x'` is the jsonb "contains this
-- key" test, so this touches only the roles that actually hold the old key.
--
-- A ROLE WITH NO PERMISSIONS AT ALL IS NOT TOUCHED, and that is correct rather
-- than an oversight: an empty array means "not configured", and has_perm()
-- falls back to the code defaults for it (which carry every non-admin module,
-- this one included). Writing one key into that row would turn the fallback OFF
-- and leave the role holding exactly one permission — the "role that sees
-- NOTHING" fault in CLAUDE.md, caused by the fix for it.
-- ===========================================================================

update public.app_roles ar
   set permissions = (
         select coalesce(jsonb_agg(distinct v), '[]'::jsonb)
           from (
             select jsonb_array_elements_text(ar.permissions) as v
             union
             select 'mod:/stock-out' as v
           ) u
       ),
       updated_at = now()
 where ar.permissions ? 'mod:/spare-dispatch'
   and not (ar.permissions ? 'mod:/stock-out');

-- ---------------------------------------------------------------------------
-- THE MENU MOVES NEED NO GRANT, and it is worth saying why rather than leaving
-- a reader to wonder what is missing.
--
-- A page's permission is `mod:<path>` — the PATH, not the heading it sits
-- under. Daily Call Review moving to Quality & Analytics, Call Review and
-- Customer Feedback to Service Calls, and the two bulk uploaders to
-- Administration change which heading they are listed beneath in the menu and
-- in the Roles & Permissions matrix; none of them changes a path, so no role
-- gains or loses access. The headings are how the matrix is READ, and matching
-- them to the menu is what stops an administrator granting the wrong row.
--
-- The two uploaders were `adminOnly` before the move and still are — their keys
-- (mod:/report-mapping, mod:/pm-bulk-upload) are unchanged, and administration
-- is where they now appear rather than a new right they now need.
-- ---------------------------------------------------------------------------

-- ------------------------------------------------------------------------
-- 0172_user_signatures.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0172 — A USER MAY SAVE THEIR SIGNATURE.
--
-- The user's ask (2026-09-12): "Add a Provision for users to Save their
-- signatures." The documents that leave this system all end in a signature
-- block somebody signs by hand after printing — the Delivery Challan's two
-- blocks, the Declaration, the Field Failure Report's "Signature:" line. A
-- saved signature is what lets the document carry it already.
--
-- WHY A TABLE OF ITS OWN RATHER THAN A COLUMN ON `profiles`.
--
-- Two reasons, and the second is the important one.
--
--  1. `profiles` cannot be written by its owner. Its only write policy is
--     `profiles_admin_write` — `has_perm('users.manage')` (0008) — so adding a
--     column there would mean either widening that policy or asking an
--     administrator to paste in everybody's signature. RLS grants by ROW, not
--     by column: a policy letting somebody update their own profile row to save
--     a signature lets them update every other field on it too, and the role
--     guard beside it exists precisely because that row is where privilege
--     lives. A separate table is the only way to say "your signature is yours"
--     without saying "your profile is yours".
--
--  2. A SIGNATURE IS NOT ORDINARY PROFILE DATA. It is the mark that stands for
--     a person's assent on a quality record. What it is worth depends entirely
--     on nobody else being able to obtain it or to set it.
--
-- SO: READ YOUR OWN, WRITE YOUR OWN, AND NOBODY ELSE'S — NOT EVEN AN
-- ADMINISTRATOR'S.
--
--   * No administrator read. An administrator has every other right in this
--     system and this one is deliberately withheld: a signature image that a
--     second person can obtain is one they can put on anything, and there is
--     then no sense in which the mark on a printed report is that person's.
--     Admins can see WHETHER somebody has saved one (the view below), which is
--     the only thing administration actually needs — to chase the ones who
--     have not.
--   * No administrator write, for the same reason stated the other way round:
--     a signature somebody else can SET is a signature nobody signed.
--   * REMOVAL is the one administrative act, and it is a FUNCTION rather than
--     a policy — see the note on usig_delete below for why a policy could not
--     express it. A person who has left should not leave their mark in the
--     database, and they are by then unable to remove it themselves. Removal
--     destroys nothing that was signed: the printed document is the record,
--     not this row.
--
-- WHAT THIS MEANS ON A DOCUMENT, and it is a real limitation rather than an
-- oversight: a document prints a saved signature only when the person printing
-- it is the person the block names. Printing somebody else's block leaves it
-- blank to be signed by hand, exactly as today. That is the correct outcome —
-- the alternative is a system that signs documents on people's behalf.
-- ===========================================================================

create table if not exists public.user_signatures (
  user_id     uuid primary key references auth.users(id) on delete cascade,
  -- A PNG data URI. Held as text rather than in a bucket: it is a few KB of
  -- ink, it is read only by the one person it belongs to, and a storage object
  -- would need its own access rules to say the same thing this table says.
  signature   text        not null default '',
  -- The name and title printed UNDER the mark. Taken from the profile when the
  -- signature is saved rather than read live, because a printed document should
  -- carry the name the person signed as.
  name_line   text        not null default '',
  title_line  text        not null default '',
  updated_at  timestamptz not null default now()
);

alter table public.user_signatures enable row level security;

-- YOUR OWN, AND ONLY YOUR OWN. Four policies rather than one `for all`, because
-- delete is the only command with a different answer and a single policy could
-- not express that.
drop policy if exists usig_read on public.user_signatures;
create policy usig_read on public.user_signatures for select to authenticated
  using (user_id = (select auth.uid()));

drop policy if exists usig_insert on public.user_signatures;
create policy usig_insert on public.user_signatures for insert to authenticated
  with check (user_id = (select auth.uid()));

drop policy if exists usig_update on public.user_signatures;
create policy usig_update on public.user_signatures for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));

-- YOURS, AND ONLY YOURS — no `or is_admin()` here, and that is a correction
-- rather than a simplification. It was written that way first and the test
-- proved it did nothing: PostgreSQL applies the SELECT policy to a
-- `DELETE ... WHERE`, because the statement has to READ the row to find it. An
-- administrator who cannot see the row therefore cannot delete it, and the
-- clause reported `DELETE 0` with no error — a permission that looks granted
-- and is not.
--
-- The two ways out are opposite in kind: give administrators a SELECT policy
-- (which hands them the image, destroying the point of the table), or make
-- removal an explicit administrative ACT with its own function. The function is
-- below.
drop policy if exists usig_delete on public.user_signatures;
create policy usig_delete on public.user_signatures for delete to authenticated
  using (user_id = (select auth.uid()));

grant select, insert, update, delete on public.user_signatures to authenticated;

-- ---------------------------------------------------------------------------
-- REMOVING A LEAVER'S SIGNATURE. A person who has left should not leave their
-- mark in the database, and they are by then unable to remove it themselves.
--
-- Definer, so it does not need a read policy to work; it returns whether there
-- was one to remove, and NEVER the signature itself — an administrator's
-- authority here is to destroy the mark, not to hold it. Nothing that was
-- signed is affected: the printed document is the record, not this row.
-- ---------------------------------------------------------------------------
create or replace function public.remove_user_signature(p_user uuid)
returns boolean language plpgsql security definer set search_path = public as $$
declare v_had boolean;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may remove another person''s signature.';
  end if;
  if p_user = auth.uid() then
    raise exception 'Use your own Profile page to remove your signature.';
  end if;
  select true into v_had from public.user_signatures where user_id = p_user;
  delete from public.user_signatures where user_id = p_user;
  return coalesce(v_had, false);
end $$;

revoke all on function public.remove_user_signature(uuid) from public;
grant execute on function public.remove_user_signature(uuid) to authenticated;

-- ---------------------------------------------------------------------------
-- THE STAMP. `updated_at` is the database's to set: a client that can choose
-- when its own signature was last changed can make one look current.
-- ---------------------------------------------------------------------------
create or replace function public.user_signature_stamp()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  -- The owner is the session's, not the caller's to name. The insert policy
  -- already refuses another user's id; this makes the column unable to CARRY
  -- one, so the two cannot disagree.
  new.user_id := coalesce(auth.uid(), new.user_id);
  new.updated_at := now();
  return new;
end $$;

drop trigger if exists zz_user_signature_stamp on public.user_signatures;
create trigger zz_user_signature_stamp before insert or update on public.user_signatures
  for each row execute function public.user_signature_stamp();

-- ---------------------------------------------------------------------------
-- WHO HAS SAVED ONE — the image deliberately absent.
--
-- This is what administration needs and all it needs: chasing the people who
-- have NOT saved a signature does not require seeing the ones who have. So this
-- returns a boolean and a date, and there is no path anywhere that returns
-- somebody else's image.
--
-- A FUNCTION, NOT A VIEW, and the difference is not stylistic. To report across
-- rows the caller cannot read it has to be `security definer`, and a definer
-- VIEW over RLS-protected tables is the exact fault this project shipped three
-- times (0040/0050/0057 — `calls` without security_invoker handed every row to
-- every signed-in user); `check:views` now refuses one, correctly, and writing
-- an exception into that check to admit this would blunt the control that
-- catches the real thing. A definer function is the instrument that says
-- "elevated on purpose" out loud, carries its own authority test, and returns
-- only the two columns it means to.
-- ---------------------------------------------------------------------------
create or replace function public.user_signature_status()
returns table (user_id uuid, full_name text, email text, has_signature boolean, signed_at timestamptz)
language plpgsql security definer set search_path = public as $$
begin
  if not (public.is_admin() or public.has_perm('users.manage')) then
    raise exception 'Only User Access may see who has saved a signature.';
  end if;
  return query
    select p.id, p.full_name, p.email,
           (s.user_id is not null and coalesce(btrim(s.signature), '') <> ''),
           s.updated_at
      from public.profiles p
      left join public.user_signatures s on s.user_id = p.id
     order by p.full_name;
end $$;

revoke all on function public.user_signature_status() from public;
grant execute on function public.user_signature_status() to authenticated;

-- ------------------------------------------------------------------------
-- 0121_rbac_policy_tail.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- rbac.sql must leave every policy it defines at its LATEST definition.
--
-- 0008 creates a policy for most tables in the schema. Six of those were later
-- narrowed by other modules — and because the apply bundles are replayed ONE AT
-- A TIME, running `rbac.sql` on its own put 0008's wider version back. No
-- error, no warning, and the bundle reports success. It has now happened twice
-- (2026-09-05 for `srl_insert`, 2026-09-06 for these six), each time reading as
-- "the migration was never applied" when it had been applied and overwritten.
--
-- 0087/0088 were fixed by MOVING them into this module. These six cannot move:
-- each sits in a migration that also does work belonging to its own module, and
-- each depends on tables that module creates. So this file — the LAST in the
-- rbac module — re-asserts their latest definitions instead:
--
--   spare_requests.sr_read        0040_spare_read_scope
--   spare_requests.sr_update      0009_spare_receipt
--   spare_request_lines.srl_update 0016_spare_line_approvals
--   spare_consumption.cons_read   0038_spare_consumption_scope
--   spare_consumption.cons_write  0059_consumption_reconciliation
--   spare_requests_stage_guard()  0016_spare_line_approvals
--   masters insert/update/delete  0067_master_list_permissions
--
-- Every block is GUARDED on what it names. On a FRESH apply rbac runs before
-- masters, spare_requests and handstock (ALL_ORDER), so those tables do not
-- exist yet: each block skips, and the owning module defines the policy itself
-- a moment later — identically. On a replay against a live database everything
-- is present, so the latest definition is restored. Idempotent either way, and
-- the definitions here are copies: change one in its own migration and change
-- it here too, or rbac.sql goes back to reverting it.
-- ===========================================================================

-- --------------------------------------------------------------------------
-- spare_requests — who may SEE one (0040), and who may UPDATE one (0009).
-- --------------------------------------------------------------------------
do $$
begin
  if to_regclass('public.spare_requests') is null then
    raise notice 'skip sr_read/sr_update — public.spare_requests is not present yet';
    return;
  end if;

  if to_regproc('public.can_view_all_calls') is not null
     and exists (select 1 from information_schema.columns
                  where table_schema = 'public' and table_name = 'spare_requests'
                    and column_name = 'engineer_email') then
    drop policy if exists sr_read on public.spare_requests;
    create policy sr_read on public.spare_requests for select
      using (
        (select public.can_view_all_calls())
        or created_by = (select auth.uid())
        or lower(engineer_email) = lower((select auth.email()))
        or lower(btrim(engineer)) in (
             select lower(btrim(n)) from public.visible_engineer_names() as v(n)
           )
      );
  else
    raise notice 'skip sr_read — can_view_all_calls() or engineer_email is not present yet';
  end if;

  if to_regproc('public.is_spare_requester') is not null then
    drop policy if exists sr_update on public.spare_requests;
    create policy sr_update on public.spare_requests for update
      using      (public.can_approve_spares() or public.is_spare_requester(spare_requests))
      with check (public.can_approve_spares() or public.is_spare_requester(spare_requests));
  else
    raise notice 'skip sr_update — is_spare_requester() is not present yet';
  end if;
end $$;

-- --------------------------------------------------------------------------
-- spare_request_lines — the raiser may touch their own lines, not only an
-- approver (0016). Without this an engineer cannot acknowledge receipt.
-- --------------------------------------------------------------------------
do $$
begin
  if to_regclass('public.spare_request_lines') is null
     or to_regproc('public.is_spare_requester') is null then
    raise notice 'skip srl_update — spare_request_lines or is_spare_requester() is not present yet';
    return;
  end if;

  drop policy if exists srl_update on public.spare_request_lines;
  create policy srl_update on public.spare_request_lines for update
    using (
      public.can_approve_spares()
      or exists (select 1 from public.spare_requests r
                  where r.uid = spare_request_lines.request_uid and public.is_spare_requester(r))
    )
    with check (
      public.can_approve_spares()
      or exists (select 1 from public.spare_requests r
                  where r.uid = spare_request_lines.request_uid and public.is_spare_requester(r))
    );
end $$;

-- --------------------------------------------------------------------------
-- spare_consumption — scoped reads (0038), and a Reconciliation line needing
-- its own permission rather than calls.report (0059).
-- --------------------------------------------------------------------------
do $$
begin
  if to_regclass('public.spare_consumption') is null then
    raise notice 'skip cons_read/cons_write — public.spare_consumption is not present yet';
    return;
  end if;

  if to_regproc('public.can_view_all_calls') is not null
     and exists (select 1 from information_schema.columns
                  where table_schema = 'public' and table_name = 'spare_consumption'
                    and column_name = 'engineer_email') then
    drop policy if exists cons_read on public.spare_consumption;
    create policy cons_read on public.spare_consumption for select
      using (
        (select public.can_view_all_calls())
        or created_by = (select auth.uid())
        or lower(engineer_email) = lower((select auth.email()))
        or lower(trim(engineer)) in (
             select lower(trim(n)) from public.visible_engineer_names() as v(n)
           )
      );
  else
    raise notice 'skip cons_read — can_view_all_calls() or engineer_email is not present yet';
  end if;

  if exists (select 1 from information_schema.columns
              where table_schema = 'public' and table_name = 'spare_consumption'
                and column_name = 'source') then
    drop policy if exists cons_write on public.spare_consumption;
    create policy cons_write on public.spare_consumption for insert
      with check (
        case when coalesce(source, 'Report') = 'Reconciliation'
             then public.has_perm('consumption.reconcile')
             else (public.has_perm('calls.report') or public.has_perm('spare.dispatch'))
        end
      );
  else
    raise notice 'skip cons_write — spare_consumption.source is not present yet';
  end if;
end $$;

-- --------------------------------------------------------------------------
-- masters — write rights are PER LIST (0067).
--
-- This is the one no static check can see: 0008 creates `masters_write`
-- through `execute format(...)` in a loop, so no `create policy` literal
-- appears in its text. Policies are OR'd, so leaving 0008's version in place
-- lets a holder of `masters.edit` write EVERY list again — exactly what 0067
-- narrowed.
-- --------------------------------------------------------------------------
do $$
begin
  if to_regclass('public.masters') is null then
    raise notice 'skip masters policies — public.masters is not present yet';
    return;
  end if;

  drop policy if exists masters_write on public.masters;
  drop policy if exists masters_admin_write on public.masters;
  drop policy if exists masters_insert on public.masters;
  drop policy if exists masters_update on public.masters;
  drop policy if exists masters_delete on public.masters;

  create policy masters_insert on public.masters for insert
    with check (public.has_perm('masters.edit')
             or public.has_perm('master.' || coalesce(name, '') || '.edit'));

  create policy masters_update on public.masters for update
    using      (public.has_perm('masters.edit')
             or public.has_perm('master.' || coalesce(name, '') || '.edit'))
    with check (public.has_perm('masters.edit')
             or public.has_perm('master.' || coalesce(name, '') || '.edit'));

  create policy masters_delete on public.masters for delete
    using      (public.has_perm('masters.edit')
             or public.has_perm('master.' || coalesce(name, '') || '.delete'));
end $$;

-- --------------------------------------------------------------------------
-- spare_requests_stage_guard() — the per-stage approval guard.
--
-- 0008 creates it; 0009, 0012 and 0016 each extend it, and 0016 has the last
-- word: the receipt columns, courier / dispatch remarks, reject_reason and the
-- Received transition. Replaying rbac.sql put 0008's back, which refuses an
-- engineer acknowledging receipt and lets a rejection be written without one.
--
-- Unlike the policies above this needs nothing that a later module creates —
-- it is plpgsql, so its body is not resolved until it runs — so it is
-- unguarded and correct on a fresh apply as well.
-- --------------------------------------------------------------------------
create or replace function public.spare_requests_stage_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if public.is_admin() then return new; end if;
  if coalesce(current_setting('app.spare_rollup', true), '') = '1' then return new; end if;

  if new.stage  is distinct from old.stage
  or new.status is distinct from old.status
  or new.rm_approval         is distinct from old.rm_approval
  or new.commercial_approval is distinct from old.commercial_approval
  or new.nsm_approval        is distinct from old.nsm_approval
  or new.stores_status       is distinct from old.stores_status
  or new.received_at         is distinct from old.received_at then
    raise exception 'Spare approvals are recorded per spare — update spare_request_lines, not the request';
  end if;
  return new;
end $$;

commit;
